   AND i.alt_text IS NOT DISTINCT FROM t.old_alt;

-- race gnomes: note_en
UPDATE battle_races
   SET note_en = $fx$Short and sturdy, they live by stone and fire.$fx$
 WHERE slug = 'gnomes'
   AND note_en IS NOT DISTINCT FROM $fx$Низкие и крепкие, живут у камня и огня.$fx$;

-- race gnomes: note_uk
UPDATE battle_races
   SET note_uk = $fx$Низькі й міцні, живуть біля каменю й вогню.$fx$
 WHERE slug = 'gnomes'
   AND note_uk IS NOT DISTINCT FROM $fx$Низкие и крепкие, живут у камня и огня.$fx$;

-- race mages: note_en
UPDATE battle_races
   SET note_en = $fx$They cast spells on command and strike from afar.$fx$
 WHERE slug = 'mages'
   AND note_en IS NOT DISTINCT FROM $fx$Колдуют по приказу и бьют издалека.$fx$;

-- race mages: note_uk
UPDATE battle_races
   SET note_uk = $fx$Чаклують за наказом і б’ють здалеку.$fx$
 WHERE slug = 'mages'
   AND note_uk IS NOT DISTINCT FROM $fx$Колдуют по приказу и бьют издалека.$fx$;

-- race people: note_en
UPDATE battle_races
   SET note_en = $fx$Ordinary folk: no spells, but they have training.$fx$
 WHERE slug = 'people'
   AND note_en IS NOT DISTINCT FROM $fx$Обычные жители: у них нет чар, зато есть выучка.$fx$;

-- race people: note_uk
UPDATE battle_races
   SET note_uk = $fx$Звичайні мешканці: чар у них немає, зате є вишкіл.$fx$
 WHERE slug = 'people'
   AND note_uk IS NOT DISTINCT FROM $fx$Обычные жители: у них нет чар, зато есть выучка.$fx$;

-- race undead: note_en
UPDATE battle_races
   SET note_en = $fx$The dead who keep on acting.$fx$
 WHERE slug = 'undead'
   AND note_en IS NOT DISTINCT FROM $fx$Умершие, которые продолжают действовать.$fx$;

-- race undead: note_uk
UPDATE battle_races
   SET note_uk = $fx$Померлі, які продовжують діяти.$fx$
 WHERE slug = 'undead'
   AND note_uk IS NOT DISTINCT FROM $fx$Умершие, которые продолжают действовать.$fx$;

-- race water: note_en
UPDATE battle_races
   SET note_en = $fx$They live in water and grow weaker on the shore.$fx$
 WHERE slug = 'water'
   AND note_en IS NOT DISTINCT FROM $fx$Живут в воде, на берегу слабеют.$fx$;

-- race water: note_uk
UPDATE battle_races
   SET note_uk = $fx$Живуть у воді, на березі слабшають.$fx$
 WHERE slug = 'water'
   AND note_uk IS NOT DISTINCT FROM $fx$Живут в воде, на берегу слабеют.$fx$;

-- race witches: note_en
UPDATE battle_races
   SET note_en = $fx$They cast curses and poison.$fx$
 WHERE slug = 'witches'
   AND note_en IS NOT DISTINCT FROM $fx$Колдуют проклятиями и ядом.$fx$;

-- race witches: note_uk
UPDATE battle_races
   SET note_uk = $fx$Чаклують прокляттями й отрутою.$fx$
 WHERE slug = 'witches'
   AND note_uk IS NOT DISTINCT FROM $fx$Колдуют проклятиями и ядом.$fx$;

-- race witch: duplicate, removed only while nothing refers to it
DELETE FROM battle_races AS r
 WHERE r.slug = 'witch'
   AND NOT EXISTS (SELECT 1 FROM battle_cards c WHERE c.race_id = r.id)
   AND NOT EXISTS (SELECT 1 FROM studio_races s WHERE s.race_id = r.id)
   AND COALESCE(r.level_frames, '') NOT LIKE '%/static/%'
   AND COALESCE(r.icon_url, '') = ''
   AND NOT EXISTS (SELECT 1 FROM battle_races o
                    WHERE o.id <> r.id AND COALESCE(o.race_damage, '') LIKE '%' || r.id::text || '%');
